export default '/**\n * Stackra file contract:\n * Purpose: the "overflow" demo of the native MultiSelect: Select all in the list, and chips past two folded into +N.\n * Boundary: a demo with no props, @stackra/ui and local state only; the same file is the preview and the code shown.\n * Runtime: react-native\n * Governing contract: showcase redesign spec (2026-10-27) section 4 (demo contract); ADR 0302 (decisions 3 and 5);\n *          ADR 0060 (light, dark, RTL); STA-1371 (wave A, owner request 2026-10-29).\n */\nimport { MultiSelect, useCatalogueText } from "@stackra/ui/native";\nimport { View } from "react-native";\n\nimport { MESSAGES } from "#src/constants/messages.constant";\nimport { MULTI_SELECT_OVERFLOW_DEMO_KEYS } from "#src/demos/free/multi-select/multi-select-overflow-demo-keys.constant";\n\n/** The demo\'s keys. */\nconst K = MULTI_SELECT_OVERFLOW_DEMO_KEYS.demo_free.multi_select_overflow;\n\n/** Multi-select: select all, and a +N overflow. */\nexport default function Overflow() {\n  const t = useCatalogueText(MESSAGES.en);\n  return (\n    <View>\n      <MultiSelect\n        label={t(K.label)}\n        hasSelectAll\n        maxVisible={2}\n        defaultValue={["ruh", "jed", "dmm", "mkk"]}\n        items={[\n          { id: "ruh", label: t(K.riyadh) },\n          { id: "jed", label: t(K.jeddah) },\n          { id: "dmm", label: t(K.dammam) },\n          { id: "mkk", label: t(K.makkah) },\n          { id: "med", label: t(K.madinah) },\n          { id: "abh", label: t(K.abha) },\n        ]}\n      />\n    </View>\n  );\n}\n';
